/**
 * geo-reload.js
 *
 * Parses an execution trace Markdown file generated by the Geo AI demo
 * and rebuilds the chat session context and display UI.
 */

/**
 * Parses a markdown string containing an execution trace (from the zippy
 * block). Extracts all the Request and Response pairs.
 *
 * @param {string} markdown - The raw markdown text containing the trace.
 * @returns {Array} Array of parsed turn objects.
 */
function parseTraceMarkdown(markdown) {
  const turns = [];

  // Regular expression to match the turn blocks in the markdown log.
  // Looks for ### Label, **Request**: ```json ... ```, **Response**: ``` ...
  // ``` Uses lazy matching ([\s\S]*?) to capture the contents of the code
  // blocks.
  const turnRegex =
      /###\s+([^\n]+)\n+[\s\S]*?(?:\*\*|)Request(?:\*\*|):\s*```(?:json)?\s*([\s\S]*?)```\s+[\s\S]*?(?:\*\*|)Response(?:\*\*|):\s*```(?:json)?\s*([\s\S]*?)```/g;

  let match;
  while ((match = turnRegex.exec(markdown)) !== null) {
    let label = match[1].trim();
    let requestJsonStr = match[2].trim();
    let responseStr = match[3].trim();

    function robustJSONParse(str) {
      str = str.trim();
      try { return JSON.parse(str); } catch (e) {}
      
      const start = str.indexOf('{');
      if (start === -1) return null;
      
      let depth = 0;
      let inString = false;
      let escapeNext = false;
      
      for (let i = start; i < str.length; i++) {
        let char = str[i];
        
        if (escapeNext) {
          escapeNext = false;
          continue;
        }
        
        if (char === '\\') {
          escapeNext = true;
          continue;
        }
        
        if (char === '"') {
          inString = !inString;
          continue;
        }
        
        if (!inString) {
          if (char === '{') depth++;
          else if (char === '}') {
            depth--;
            if (depth === 0) {
              try {
                return JSON.parse(str.substring(start, i + 1));
              } catch (e) {
                // Keep searching in case it's a false positive or inner brace? No, depth 0 means root object is closed.
                return null;
              }
            }
          }
        }
      }
      return null;
    }

    let requestObj = robustJSONParse(requestJsonStr);
    if (!requestObj) {
      console.warn(`Failed to parse request JSON for ${label}`);
    }

    // Attempt to parse response as JSON for easier processing later
    let responseObj = robustJSONParse(responseStr);
    if (!responseObj) {
      // It might just be raw text, or malformed JSON
      responseObj = responseStr;
    }

    turns.push({
      label: label,
      request: requestObj,
      response: responseObj,
      rawResponse: responseStr
    });
  }
  return turns;
}

/**
 * Rebuilds the internal application state and triggers a UI recreation from
 * parsed turns. This depends on the global state variables in geo-chat.js
 * like `chat_history`.
 *
 * @param {string} markdownTrace - The raw trace text.
 */
function restoreChatSession(markdownTrace) {
  const turns = parseTraceMarkdown(markdownTrace);
  if (!turns || turns.length === 0) {
    console.warn('No turns found in the trace file to restore.');
    return;
  }

  // 1. Restore App Memory and find explicit user prompts
  let restoredMemory = {};
  let userPrompts = [];

  turns.forEach(turn => {
    // Rebuild memory from data stores in execution steps
    if (typeof turn.response === 'object' && turn.response !== null) {
      if (turn.response.data && turn.response.save_as) {
        restoredMemory[turn.response.save_as] = turn.response.data;
      }
    }

    // Find explicit user prompts by checking the last message in Turn 1
    // interactions
    if (turn.label.includes('Turn 1') && turn.request &&
        turn.request.contents) {
      const contents = turn.request.contents;
      if (contents.length > 0) {
        const lastMsg = contents[contents.length - 1];
        if (lastMsg.role === 'user') {
          userPrompts.push(lastMsg.parts[0].text);
        }
      }
    }
  });

  // 2. Restore chat_history context
  // The most complete chat_history (excluding internal execution prompts) is
  // contained in the contents array of the last Turn 2 log.
  let mostRecentTurn2 =
      turns.slice().reverse().find(t => t.label.includes('Turn 2'));
  let restoredHistory = [];
  if (mostRecentTurn2 && mostRecentTurn2.request &&
      mostRecentTurn2.request.contents) {
    // The last item in Turn 2 request is the internal "generate step-by-step
    // plan" prompt, so we slice it out to get the genuine chat history to send
    // for future turns.
    restoredHistory = mostRecentTurn2.request.contents.slice(0, -1);
  } else if (turns.length > 0) {
    // Fallback if Turn 2 is missing
    let lastTurn = turns[turns.length - 1];
    if (lastTurn.request && lastTurn.request.contents) {
      restoredHistory = lastTurn.request.contents;
    }
  }

  // 3. Mutate live globals defined in geo-chat.js
  if (typeof chat_history !== 'undefined') {
    chat_history.length = 0;  // clear existing array
    restoredHistory.forEach(h => chat_history.push(h));
  }

  if (typeof app_memory !== 'undefined') {
    // clear existing object props
    Object.keys(app_memory).forEach(k => delete app_memory[k]);
    Object.assign(app_memory, restoredMemory);
  }

  // Hide the welcome screen when trace is reloaded
  document.body.classList.add('prompt-active');
  const welcomeScreen = document.getElementById('welcome-screen');
  if (welcomeScreen) {
    welcomeScreen.classList.add('hidden');
  }

  // 4. Robust UI visual restoration
  const chatContainer = document.getElementById('chat');
  if (!chatContainer) return;
  chatContainer.innerHTML = '';  // clear current chat session

  let currentResponseDiv = null;
  let currentContentDiv = null;
  let lastParentStepName = null;
  let currentExecStepPre = null;

  turns.forEach((turn) => {
    if (turn.label.includes('Turn 1')) {
      if (turn.request && turn.request.contents &&
          turn.request.contents.length > 0) {
        const lastMsg = turn.request.contents[turn.request.contents.length - 1];
        if (lastMsg.role === 'user') {
          if (typeof add_prompt === 'function') {
            add_prompt(lastMsg.parts[0].text);
          }
          currentResponseDiv = document.createElement('div');
          currentResponseDiv.className = 'response';
          chatContainer.appendChild(currentResponseDiv);

          let step1_div = document.createElement('div');
          step1_div.className = 'step-result';
          let thoughts = (turn.response && turn.response.thoughts) ? turn.response.thoughts : '';
          let intent = (turn.response && turn.response.intent) ? turn.response.intent : '';
          let title = 'Understanding';
          if (intent === 'chat') title = 'Conversation';
          if (intent === 'new_analysis' && (!turn.response.analysis_spec || turn.response.analysis_spec.length === 0)) title = 'Request Rejected';
          if (intent === 'execute') title = 'Execution Confirmed';
          
          step1_div.innerHTML =
              `<details><summary><span class="checkmark"></span>${title}</summary><div class="transcript-wrapper"><pre class="zippy-content">Analyzing input:\n${
                  thoughts}</pre><button class="copy-button" data-tooltip="Copy to clipboard"></button></div></details>`;
          currentResponseDiv.appendChild(step1_div);

          currentContentDiv = document.createElement('div');
          currentResponseDiv.appendChild(currentContentDiv);

          if (turn.response && typeof turn.response === 'object') {
            let p = document.createElement('p');
            p.className = 'text-paragraph tighter-margin';
            p.innerHTML = renderMarkdownBold(turn.response.summary || 'Summary missing.');
            currentContentDiv.appendChild(p);

            if (turn.response.assumptions &&
                Array.isArray(turn.response.assumptions) &&
                turn.response.assumptions.length > 0) {
              let assoc = document.createElement('p');
              assoc.className = 'assumptions-header';
              assoc.textContent = `Defaults and assumptions:`;
              currentContentDiv.appendChild(assoc);
              let ul = document.createElement('ul');
              ul.className = 'bulleted-list assumptions-list';
              turn.response.assumptions.forEach(assm => {
                let li = document.createElement('li');
                li.innerHTML = renderMarkdownBold(assm);
                ul.appendChild(li);
              });
              currentContentDiv.appendChild(ul);
            }
          }
        }
      }
    }

    if (turn.label.includes('Turn 2') && currentResponseDiv !== null) {
      if (turn.response && typeof turn.response === 'object') {
        let step2_div = document.createElement('div');
        step2_div.className = 'step-result';
        let thoughts2 = (turn.response.thoughts) ? turn.response.thoughts : '';
        step2_div.innerHTML =
              `<details><summary><span class="checkmark"></span>Strategic Plan</summary><div class="transcript-wrapper"><pre class="zippy-content">Generating strategic plan:\n${
                  thoughts2}</pre><button class="copy-button" data-tooltip="Copy to clipboard"></button></div></details>`;
        // Insert it BEFORE the currentContentDiv if it exists? Wait, in live, step2_div is appended to response_div directly, and THEN content2_div is appended. 
        // But in reload, Turn 1 summary is already appended to currentContentDiv!
        // In live chat: step1_div (understanding) -> content1_div (summary, assumptions) -> step2_div (strategic plan) -> content2_div (numbered plan list).
        currentResponseDiv.appendChild(step2_div);
        
        // Let's create a new content div for the plan
        let planContentDiv = document.createElement('div');
        currentResponseDiv.appendChild(planContentDiv);
        
        if (turn.response.plan && Array.isArray(turn.response.plan) &&
            turn.response.plan.length > 0) {
          let ol = document.createElement('ol');
          ol.className = 'numbered-list';
          turn.response.plan.forEach((s) => {
            let li = document.createElement('li');
            let p = document.createElement('p');
            p.className = 'text-paragraph tighter-margin';
            p.innerHTML = `<b>${s.name}:</b> ${renderMarkdownBold(s.step)}`;
            li.appendChild(p);
            if (s.substeps && s.substeps.length > 0) {
              let ul = document.createElement('ul');
              ul.className = 'bulleted-list';
              s.substeps.forEach(substep => {
                let inner_li = document.createElement('li');
                inner_li.innerHTML = renderMarkdownBold(substep);
                ul.appendChild(inner_li);
              });
              li.appendChild(ul);
            }
            ol.appendChild(li);
          });
          planContentDiv.appendChild(ol);
        }
      }
    }

    if (turn.label.includes('Execution Step') && currentResponseDiv !== null) {
      if (turn.response && typeof turn.response === 'object') {
        let fullLabel = turn.label.replace('Execution Step - ', '').trim();
        let isBreakdown = fullLabel.endsWith('\u2002...');
        let parentStepName = fullLabel;
        let subStepName = '';

        if (isBreakdown) {
          parentStepName = fullLabel.substring(0, fullLabel.length - 4);
        } else if (fullLabel.includes('\u2002...\u2002')) {
          let parts = fullLabel.split('\u2002...\u2002');
          parentStepName = parts[0];
          subStepName = parts[1];
        }

        if (parentStepName !== lastParentStepName) {
          let exec_step_div = document.createElement('div');
          exec_step_div.className = 'step-result';
          exec_step_div.innerHTML =
              `<details><summary><span class="checkmark"></span><span class="label-text">${
                  parentStepName ||
                  'Execution Step'}</span></summary><div class="transcript-wrapper"><pre class="zippy-content"></pre><button class="copy-button" data-tooltip="Copy to clipboard"></button></div></details>`;
          currentResponseDiv.appendChild(exec_step_div);
          currentExecStepPre = exec_step_div.querySelector('.zippy-content');
          lastParentStepName = parentStepName;
        }

        if (!isBreakdown) {
          let step_debug_text = '';
          if (turn.response.summary) {
            let p = document.createElement('p');
            p.className = 'text-paragraph';
            p.innerHTML = renderMarkdownBold(turn.response.summary);
            currentResponseDiv.appendChild(p);
          }

          if (typeof render_visualizations === 'function') {
            step_debug_text =
                render_visualizations(turn.response, currentResponseDiv) || '';
          }

          if (turn.response.data_sources &&
              turn.response.data_sources.length > 0) {
            let src_header = document.createElement('div');
            src_header.className = 'text-paragraph source-header';
            src_header.textContent = 'Data Sources:';
            currentResponseDiv.appendChild(src_header);

            let ul = document.createElement('ul');
            ul.className = 'bulleted-list tight-list';
            turn.response.data_sources.forEach(src => {
              let li = document.createElement('li');
              li.className = 'text-paragraph';
              li.innerHTML = renderMarkdownBold(src);
              ul.appendChild(li);
            });
            currentResponseDiv.appendChild(ul);
          }

          if (currentExecStepPre) {
            let full_rationale =
                turn.response.thoughts || 'No details provided.';
            if (step_debug_text)
              full_rationale += '\n\n' + step_debug_text.trim();
            let text_block =
                `[${subStepName || parentStepName}]\n${full_rationale}\n\n`;
            currentExecStepPre.textContent += text_block;
          }
        }
      }
    }
  });


  // Append Execution trace zippy for reloaded results
  if (currentResponseDiv !== null && turns.length > 0) {
    let turn_transcript = '';
    turns.forEach((turn) => {
      turn_transcript += `### ${turn.label || 'Turn'}\n\n**Request**:\n\`\`\`json\n${
          JSON.stringify(turn.request, null, 2)}\n\`\`\`\n\n**Response**:\n\`\`\`\n${
          turn.rawResponse || JSON.stringify(turn.response, null, 2)}\n\`\`\`\n\n`;
    });

    let transcript_step_div = document.createElement('div');
    transcript_step_div.className = 'step-result';
    let transcript_details = document.createElement('details');
    let transcript_summary = document.createElement('summary');
    transcript_summary.innerHTML =
        `<span class="transcript-icon"></span><span class="label-text">Execution trace</span>`;

    let transcript_wrapper = document.createElement('div');
    transcript_wrapper.className = 'transcript-wrapper';

    let copy_btn = document.createElement('button');
    copy_btn.className = 'copy-button';
    copy_btn.setAttribute('data-tooltip', 'Copy to clipboard');
    copy_btn.onclick = function(e) {
      navigator.clipboard.writeText(turn_transcript);
    };

    let transcript_pre = document.createElement('pre');
    transcript_pre.className = 'zippy-content';
    transcript_pre.textContent = turn_transcript;

    transcript_wrapper.appendChild(transcript_pre);
    transcript_wrapper.appendChild(copy_btn);

    transcript_details.appendChild(transcript_summary);
    transcript_details.appendChild(transcript_wrapper);
    transcript_step_div.appendChild(transcript_details);
    currentResponseDiv.appendChild(transcript_step_div);
  }

  if (typeof scrollToBottom === 'function') {

    scrollToBottom();
  }
}

/**
 * Helper to fetch and load a trace from the server given a query param on page
 * load. Example URL: /index.html?trace=chat_trace.md
 */
async function loadTraceFromQueryParam() {
  const urlParams = new URLSearchParams(window.location.search);
  let traceFile = urlParams.get('trace');

  if (traceFile) {
    try {
      // Prevent basic path traversal security issues if hosted loosely
      traceFile = traceFile.replace(/\.\.\//g, '');
      
      // Always fetch as .txt to avoid x20web automatically rendering .md files as HTML
      const fetchUrl = traceFile.replace(/\.md$/, '.txt');
      const resp = await fetch(fetchUrl);

      if (resp.ok) {
        const markdownTrace = await resp.text();
        // Adding a small timeout to let the DOM init functions (like
        // initialize) finish
        setTimeout(() => restoreChatSession(markdownTrace), 100);
      } else {
        console.error('Failed to fetch trace:', resp.statusText);
      }
    } catch (e) {
      console.error('Error fetching trace file:', e);
    }
  }
}

// Automatically execute when the DOM is ready
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', loadTraceFromQueryParam);
} else {
  loadTraceFromQueryParam();
}
